class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("pins must be between 0 and 10")

        if len(self.rolls) >= 21:
            raise Exception("cannot roll after the game is complete")

        if self._in_tenth_frame():
            self._roll_tenth_frame(pins)
        else:
            self.rolls.append(pins)

    def _in_tenth_frame(self):
        rolls = self.rolls
        if len(rolls) < 18:
            return False
        if len(rolls) >= 21:
            return False
        # Frames 1-9 consume 18 rolls; check whether they are complete.
        i = 0
        for _ in range(9):
            if rolls[i] == 10:
                i += 1
            else:
                i += 2
        return i == 18

    def _roll_tenth_frame(self, pins):
        rolls = self.rolls
        tenth = rolls[18:]
        if not tenth:
            self.rolls.append(pins)
        elif len(tenth) == 1:
            if tenth[0] == 10:
                self.rolls.append(pins)
            else:
                if tenth[0] + pins > 10:
                    raise Exception("two rolls in a frame cannot score more than 10 points")
                self.rolls.append(pins)
        else:
            # Third roll of the tenth frame.
            if tenth[0] == 10 and tenth[1] != 10:
                if tenth[1] + pins > 10:
                    raise Exception("two rolls in a frame cannot score more than 10 points")
            self.rolls.append(pins)

    def score(self):
        rolls = self.rolls
        if not self._game_complete():
            raise Exception("cannot score an incomplete game")

        total = 0
        i = 0
        for frame in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            else:
                if rolls[i] + rolls[i + 1] == 10:
                    total += 10 + rolls[i + 2]
                else:
                    total += rolls[i] + rolls[i + 1]
                i += 2
        return total

    def _game_complete(self):
        rolls = self.rolls
        i = 0
        for frame in range(9):
            if i >= len(rolls):
                return False
            if rolls[i] == 10:
                i += 1
            else:
                i += 2
        if len(rolls) < i + 2:
            return False
        tenth = rolls[i:]
        if tenth[0] == 10:
            if len(tenth) < 3:
                return False
            if tenth[1] != 10 and len(tenth) < 3:
                return False
            return True
        if tenth[0] + tenth[1] == 10:
            return len(tenth) == 3
        return len(tenth) == 2

