class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 0
        self.frame_rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("pins must be between 0 and 10")

        if self.frame == 10:
            raise Exception("cannot roll after the game is complete")

        fr = self.frame_rolls
        if self.frame < 9:
            if fr and fr[0] != 10 and fr[0] + pins > 10:
                raise Exception("two rolls in a frame cannot score more than 10 points")
        else:
            self._validate_tenth_roll(pins)

        self.rolls.append(pins)
        fr.append(pins)

        if self._frame_complete():
            self.frame += 1
            self.frame_rolls = []

    def _validate_tenth_roll(self, pins):
        fr = self.frame_rolls
        if not fr:
            return
        if len(fr) == 1:
            if fr[0] != 10 and fr[0] + pins > 10:
                raise Exception("two rolls in a frame cannot score more than 10 points")
        else:
            if fr[0] == 10:
                if fr[1] != 10 and fr[1] + pins > 10:
                    raise Exception("two rolls in a frame cannot score more than 10 points")
            elif fr[0] + fr[1] < 10:
                raise Exception("cannot roll after the game is complete")

    def _frame_complete(self):
        fr = self.frame_rolls
        if self.frame < 9:
            return fr[0] == 10 or len(fr) == 2
        if fr[0] == 10:
            return len(fr) == 3
        return len(fr) == 2 and (fr[0] + fr[1] < 10 or len(fr) == 3)

    def score(self):
        if self.frame != 10:
            raise Exception("cannot score an incomplete game")

        total = 0
        i = 0
        for _ in range(10):
            if self.rolls[i] == 10:
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                i += 1
            else:
                if self.rolls[i] + self.rolls[i + 1] == 10:
                    total += 10 + self.rolls[i + 2]
                else:
                    total += self.rolls[i] + self.rolls[i + 1]
                i += 2
        return total

